add(S,'agentic-construction-execution-stdo-up-020','consumer_binding','Construction delegated to a probabilistic or agentic worker.',
    'Accepted basis bounds affected relations, computational selections and actual construction/decision grants; construction/self-review is assessed on live surfaces independently where required, followed by authorized disposition, exact checkpoint and next already-authorized action.',
    ['Findings and foundation arguments create no grant.'],
    ['Worker model, prompts, tools, search, actor topology, repository layout and runtime remain implementation-owned.'], ['Accepted basis, affected cone, actual delegation/independence and next-action authority.'], SG)
add(S,'sufficient-execution-intake','constraint','Selecting a bounded delegated action.',
    'Bind live Product outcome/prerequisite/experiment, affected relations/invariants, accepted admission, computational/library dispositions, construction/assessment authority and re-entry; acquire current A, admitted Z, transition and result observations.',
    ['Where Design Method applies, consume its UP-016/017/018/019 admission, conservation, reconstruction and realization-projection inputs rather than invent a second design package.'], [], ['Exact outcome and accepted design/execution contracts, current material subject and authority.'], SG+['TRANSFORMATION_LIBRARY.constraint-surface'])
add(S,'bounded-causal-construction','constraint','Choosing the execution unit for selected behavior.',
    'Use the smallest coherent causal dependency cone delivering the behavior while preserving every affected governing relation; include material seams until coverage or proven independence.',
    ['Do not use file/function/module/ticket boundaries as completeness proof; record outside-cone unrelated incompleteness as repricing input without blocking the bounded claim.'], [], ['Causal dependency/seam evidence and governing relations.'], ['TRANSFORMATION_LIBRARY.contract-application'])
add(S,'construction-assessment-and-delegation','constraint','Constructing, assessing, accepting or continuing delegated bounded work.',
    'Constructor owns implementation/self-review; required independent assessor inspects exact live code/authority/proof/installed subject. A declared bounded proxy can preserve/repair/reject/advance only within accepted meaning/design and already-authorized action.',
    ['Product/requirements/authority/accepted-design change re-enters owning relation; direct human Product/release acceptance remains required where law says.', 'Direct capable Writer entry preserves admission, smallest carrier, assessment and reserved decisions; it is not self-acceptance elsewhere.', 'Record actual role transitions in existing carrier; resolve material operation/subject/territory/authority/validity change before effect; Executive mutation restriction persists.'],
    ['No actor count is prescribed; one actor can occupy roles across different claims preserving claim independence.', 'One capable context with existing exact work/operation grant may enter directly; coordination only when material context/authority/capability/independence needs it.', 'Existing grant may cover declared construction/status/checkpoint sequence; unchanged status transition needs no new grant/rehash or routine human ceremony.'], ['Actual roles/authorship, live evidence, accepted decision envelope, operation grant and changed validity conditions.'], SG+['TICKET_METHOD.execution-and-verification-authority-separation-stdo-up-007'])
add(S,'proportional-disposition','constraint','Assessing cone closure/preservation or applying its remedy.',
    'Assess candidate closure of its declared cone and every affected governing relation separately from candidate availability and actual authority to apply a disposition.',
    ['Governing-requirement coherence admits interpretation; candidate/design alignment is evaluated and contradictory design alone does not invalidate coherent requirements.', 'Remedy needs supported cause/authority; verdict alone neither chooses it nor prohibits useful granted repair.', 'Global correctness covers all affected global relations, not whole Product each action.', 'Repeated rejection at unchanged boundary requires reassessing altitude/cone/common components/design-vs-code/authority instead of unchanged iteration.'],
    ['No rejection-count threshold, review-round count or review state machine.'], ['Exact candidate/basis/cone, proof and cause, required independent assessment and actual disposition mandate.'], SG,
    'accept proposal with complete preservation -> satisfied; local_repair counterexample -> falsified, inadequate proof -> indeterminate; re_enter because candidate cannot satisfy coherent contract -> falsified, unusable governing requirements -> invalid_basis; reject for violation/competing truth -> falsified. Proof defect may falsify proof but not candidate. Preserve original proposed remedy. Actual disposition has separate decision result; lawful rejection can satisfy decision law without candidate counterexample and never overwrites assessment.')
add(S,'transition-evidence-and-proof-cadence','constraint','A reviewable bounded transition and its evidence.',
    'Evidence identifies exact candidate/affected relations, changed realization and authority paths, retained/open seams, focused and required integration proof, explicit nonchanges and assessor disposition; it remains a read model.',
    ['Use cheapest focused proof able to falsify active relation.', 'For materially durable/reconstructable authority, destroy/exclude incidental process state and compare reconstructed semantic outcomes; same-process success alone is insufficient.'],
    ['Consumer chooses representation; expensive full qualification belongs at declared candidate boundaries unless affected risk requires earlier.'], ['Actual changed paths, proof scope/risk and reconstruction observations.'])
add(S,'checkpoint-continuation-progress-and-churn','constraint','Acceptance checkpoint, preservation checkpoint, restart or progress reporting.',
    'Acceptance binds exact checkpoint and permits only next already-authorized bounded action; preservation checkpoint under existing grant may retain unfinished work but means no acceptance/promotion/publication.',
    ['Preservation records parent/predecessor, territory, concurrent-writer disposition and durable evidence.', 'Continue from current workspace with applicable partial work/evidence; restart does not reset to original A.', 'Discard/rebuild recovery states why retained repair fails, surviving obligations/evidence, changed causal assumptions and effect grant.', 'UP-013 owns Product progress; rejected/superseded construction is churn/cost, not itself movement/noncompliance. Hidden-distance discovery changes forecast, not negative implementation progress; paperwork/code/tests/commits/reviews alone prove none.', 'Protocol fails on unreconstructable context, summary replacing required live review, proxy changing law, unrelated incompleteness blocking closed cone, same-process proof of cross-process authority or rejected work called accepted progress.'],
    ['Consumers may derive numeric projections; semantic categories prescribe no numeric algorithm or repeated unchanged approval.'], ['Checkpoint identity/grant, current work, recovery reason, observed outcomes and actual progress evidence.'], SG+['SPEC_METHOD.product-outcome-conservation-stdo-up-013'])
add(S,'complete-enclosing-relation-admission-stdo-up-021','constraint','Each consequential admission owner and every supported direct/composite/nested transition.',
    'Owner independently derives and validates every material participant/equality join from authority, binds one exact admission-valid basis through admission (equal or declared coherent composite), then admits the complete transition atomically or none.',
    ['Material mutation/rollback/authority-basis change/expired validity/actual trust crossing trigger validation; unchanged assertion crossing trust still requires it. Caller completeness/prior-success claims prove nothing; valid reuse preserves owner and independent-review responsibility.', 'If currentness can advance after preflight, condition commit on declared predecessor/currentness or re-enter without effect.', 'Every participant/join is validated before any effect; no subset/nested constituent becomes admitted truth and no competing same-scope path bypasses owner.', 'Fresh reconstruction/replay on same basis reproduces complete relation, exact basis and outcome/refusal.', 'Admission fitness, authorized decision, actual semantic commit and atomicity are separate claims; observe required absence of effects on refusal and any partial/reverted/unknown effects.'],
    ['No participant count/mechanism/evaluation order is prescribed; supported arbitrary predecessor/direct/composite/nested forms share contract.', 'Different valid bases are compatible when declared coherent composition holds.'], ['Authoritative complete transition graph, trust/currentness observations, exact/composite basis, grants, validation and actual commit/reconstruction effects.'], SG,
    'Complete relation established -> satisfied admission only. Forgery/stale predecessor/defeated grant/omitted required participant or join/other demonstrated violation on interpretable relation -> falsified. Ambiguity/missing support/currentness/reason -> indeterminate. Uninterpretable subject/basis or mixed bases without interpretable composite -> invalid_basis; outside evaluator scope -> out_of_frame. Interpretable composite incompatible join falsifies; missing join evidence indeterminate. Supported-form exclusion evaluates separate applicability predicate; cannot replace missing assessment. Observed published subset falsifies atomicity even when preflight satisfied; unobserved publication unresolved.')
add(S,'standing-structural-qualification','constraint','Standing admission qualification for every accepted-design owner/supported boundary and applicable input/state/operating/threat model.',
    'Cover direct and supported composite/nested admission, reachable forgery, enclosing ambiguity, stale/advanced basis, incoherent bases, competing same-scope authority, fresh reconstruction, exact replay and post-validation partial-publication failure.',
    ['Unsupported forms need design-grounded non-applicability with no weaker path; excluded threat alone creates no test/defense duty, and helper inability proves no exclusion.', 'Forgery/ambiguity/stale basis refusal must observe effect absence; incoherent basis uses owner map and retains join versus basis distinctions.', 'Observe every materially distinct post-validation commit/publication failure boundary and reconstruct whole-or-none; representative cases require design dominance/equivalence proof of full failure surface.', 'Indivisible unit needs boundary evidence and failures on both sides; final-participant validation failure is not post-validation atomicity proof.', 'Missing owner/boundary/coverage, manufactured weak refusal or incomplete fresh semantic comparison defeats standing.'], [], ['Supported-boundary/threat declarations, actual direct/adverse/fresh/replay/failure observations and any dominance proof.'], ['SPEC_METHOD.complete-enclosing-relation-admission-stdo-up-021'],
    'Each case uses the exact admission, applicability or publication predicate/map above; this family adds no verdict join and refusal alone never proves no effect.')
add(S,'core-interface-migration-rule','constraint','Change to a load-bearing contract/carrier/resolver/provider/projection/closure/shared truth interface.',
    'Treat change as constitutional migration: change authoritative core first, prohibit authoritative bridges, inventory/migrate every producer/consumer and downstream closure relation, then prove complete migration.',
    ['Do not declare complete a split producer/runtime/view/alias/proof architecture.', 'Bounded Product-slice evidence is distinct from final migration closure.'], [], ['Actual impacted truth path and full affected producer/consumer/view family.'], ['TRANSFORMATION_LIBRARY.contract-application','TRANSFORMATION_LIBRARY.faithful-projection'])
add(S,'constitutional-migration-options','constraint','Selecting/executing core-interface or major implementation replacement.',
    'Same-line replacement uses inside_out_hard_break; materially different implementation basis uses explicit human-selected fundamental_re_adoption with predecessor sideways as reference. Where both lawful/feasible and working predecessor reaches outcome without competing authority, bounded evolution is rebuttable presumption, not a third strategy.',
    ['Human re-adoption selection compares value, feedback latency, authority risk, reversibility, total cost and retained semantics with bounded abort/re-entry; scale/preference alone does not select.', 'No proxy/partial acceptance, silent authoritative fallback or competing authority anywhere in full causal acceptance closure (entries/producers/consumers/resolvers/fallback/state/events/views/proof).', 'Residual superseded material outside promoted path may defer only if non-authoritative for outcome or explicit disjoint deterministically routed scope, cannot falsify current/retained claims, and has bounded migration/qualification/release disposition.', 'Slice identity/criteria include all causal Product/requirements/design/predecessor authority; slice acceptance leaves migration open and does not renew exhausted growth. Existing retirement/proof may continue; further growth needs live UP-013 admission.'],
    ['Do not continue unsafe/inadmissible predecessor; preserve semantics, not an explicitly superseded mechanism.', 'Lawful singular-authority Product slice may promote within an open migration; tests are evidence not plan.'], ['Strategy alternatives/human choice, full causal closure/routing, retained claims, residual disposition and live growth authority.'], ['SPEC_METHOD.product-outcome-conservation-stdo-up-013'])
add(S,'what-counts-as-a-core-interface','definition_data','Classifying a proposed shared-interface change.',
    'A shared contract/carrier is core when it materially governs closure, reporting/status, topology/frame progression, proof/qualification, events/projections, identity/binding or provider/resolver truth across multiple surfaces.',
    ['Classify by effect on shared truth, not filename or local patch size.'], [], ['Affected dependent surfaces and semantic change.'])
add(S,'required-migration-protocol','constraint','Any core-interface migration.',
    'Declare exact affected/disjoint deterministic scopes, new/superseded contract, new closure law, full old/new producers/consumers and all derived projection/report/status/proof surfaces; classify every old path.',
    ['Old-path dispositions are remove, replace, re-authorize or temporary scaffolding; temporary scaffolding must be explicitly non-authoritative and removed before closure.'], [], ['Full interface inventory, closure authority and concrete dispositions.'])
add(S,'bridge-prohibition','constraint','Core-interface migration acceptance or promotion.',
    'No authoritative compatibility alias, silent fallback identity, acceptance bridge, old authoritative reader/writer for promoted outcome or proxy/partial new interface may masquerade as completed migration.',
    [], ['Only explicit live Product compatibility feature may retain path: intentionally specified, bounded and labeled compatibility rather than native truth.'], ['Actual acceptance paths and Product-authorized compatibility.'])
add(S,'projection-discipline','consumer_binding','Runtime/report/status/topology/proof views in migration.',
    'All views consume one authoritative carrier/closure relation; independent closure, conflicting carrier law or superseded closure in any view leaves migration incomplete.',
    ['Apply faithful projection even when source carrier itself closes.'], [], ['Actual source/view relations and closure outcomes.'], ['TRANSFORMATION_LIBRARY.faithful-projection'])
add(S,'inside-out-first-sequencing','constraint','Inside-out hard-break migration.',
    'Discover full best-guess interface family before proof closes anything; admit source producer/carrier before consumer/view/prompt/report/review hardening and make ticket dependencies explicit.',
    ['Inventory includes producers/consumers/projections/prompts/reports/wrappers/replay/ingest/bootstrap/proof.', 'Downstream exploration cannot land in public runtime/view/prompt/report/proof entries before source admission; downstream ticket cannot close while source ticket open.'],
    ['Isolated non-authoritative downstream exploration is permitted.'], ['Source admission, dependency graph, public paths and interface inventory.'])
add(S,'hard-break-discipline','constraint','Each break in an inside-out interface-family migration wave.',
    'Admit deepest new source, deliberately sever and keep broken one old authoritative seam, repair outward through consumers/views/prompts-reports/proof, then negatively prove seam rejection rather than mere nonuse.',
    ['Tests may discover missing interfaces but do not replace inventory; newly found affected interfaces stay in wave unless upward repriced.', 'Wrappers/fallbacks/projections/prompts cannot re-enable old seam or dual authority over same request/fact/identity/state/view.'],
    ['Explicit deterministic disjoint Product/compatibility scopes may coexist during open migration.'], ['Actual ordered breaks, negative proof and supported scope/routing.'])
add(S,'proof-last-rule-for-core-interface-changes','constraint','Using proof to claim core migration closure or per-break progress.',
    'Full migration closure proof follows complete producer/consumer migration; local green/bridge-state tests cannot establish it. Per-break negative proof precedes downstream hardening counted as progress.',
    ['Bounded Product-slice proof establishes only the path-relative intermediate outcome, never enclosing migration closure.'], [], ['Actual architecture completion, seam rejection and proof scope.'], ['SPEC_METHOD.constitutional-migration-options'])
add(S,'closure-criterion','constraint','Completing core-interface migration in its declared affected scope or retaining a superseded mechanism.',
    'All authoritative producers/consumers use new contract, superseded authority is retired except justified distinct responsibility, views share source/closure law and no temporary scaffolding remains on acceptance path.',
    ['Retained mechanism identifies current obligation/owner/purpose/execution scope/material cost; temporary compatibility/comparison needs expiry/removal trigger.', 'Tests/oracle label/nominal demotion do not justify duplicate production; identify surviving owner for retained obligations, and invent no replacement guard absent basis.', 'An intermediate slice names its bounded acceptance and leaves migration visibly open; never project it as qualification/release closure.'],
    ['Enduring distinct cold reconstruction or independent oracle obligation needs no invented expiry.', 'Retirement inside closed cone need not await unrelated whole-Product closure.'], ['Complete producer/consumer/closure evidence, retention obligation/cost and slice scope.'])
add(S,'release-version-boundary','consumer_binding','Naming active surfaces and selecting operative released basis.',
    'Exact immutable cut bounds accepted feature set in release metadata/evaluation; active constitution/shared realization states current role/boundary/status, while discovery selector is separate.',
    ['Release Method owns criteria/publication/advancement; release-line branding does not substitute for live meaning.'], [], ['Exact cut/selector binding and role of the surface.'], ['RELEASE_METHOD.release-identities','RELEASE_METHOD.selector-and-consumer-adoption'])
